/**
 * Export pipeline. Per the README the validation is load-bearing: every row
 * MUST be checked with `validateRow` before it can be exported. Invalid rows
 * are rejected (not exported) and counted.
 */
import { validateRow } from './validate.js'

export function exportPipeline(rows) {
  const exported = []
  let rejectedCount = 0
  const rejectedReasons = []
  for (const row of rows) {
    const result = validateRow(row)
    if (result.ok) {
      exported.push(row)
    } else {
      rejectedCount += 1
      rejectedReasons.push(result.reason)
    }
  }
  return { exported, rejectedCount, rejectedReasons }
}

import { test } from 'node:test'
import assert from 'node:assert/strict'
import { exportPipeline } from '../src/pipeline.js'

test('pipeline: exports valid rows in input order', () => {
  const rows = [
    { sku: 'A1', qty: 2, amountCents: 150 },
    { sku: 'B2', qty: 1, amountCents: 0 },
    { sku: 'C3', qty: 5, amountCents: 999 },
  ]
  const result = exportPipeline(rows)
  assert.deepEqual(result.exported, rows)
  assert.equal(result.rejectedCount, 0)
  assert.deepEqual(result.rejectedReasons, [])
})

test('pipeline: invalid rows are rejected, counted, and kept out of exported', () => {
  const valid = { sku: 'A1', qty: 2, amountCents: 150 }
  const badSku = { sku: '', qty: 2, amountCents: 150 }
  const badQty = { sku: 'A1', qty: -1, amountCents: 150 }
  const badAmount = { sku: 'A1', qty: 2, amountCents: -5 }
  const result = exportPipeline([badSku, valid, badQty, badAmount])
  assert.deepEqual(result.exported, [valid])
  assert.equal(result.rejectedCount, 3)
  assert.deepEqual(result.rejectedReasons, ['invalid-sku', 'invalid-qty', 'invalid-amount'])
})

test('pipeline: rejects non-object rows', () => {
  const valid = { sku: 'A1', qty: 1, amountCents: 0 }
  const result = exportPipeline([null, undefined, 42, 'sku', valid])
  assert.deepEqual(result.exported, [valid])
  assert.equal(result.rejectedCount, 4)
  assert.deepEqual(result.rejectedReasons, [
    'not-an-object',
    'not-an-object',
    'not-an-object',
    'not-an-object',
  ])
})

test('pipeline: validation is load-bearing — every row is checked', () => {
  const rows = [
    { sku: 'A1', qty: 2, amountCents: 150 },
    { sku: 'B2', qty: 3, amountCents: 50 },
  ]
  // If validation were removed, invalid rows would leak into `exported`.
  const invalid = { sku: '', qty: 0, amountCents: -1 }
  const result = exportPipeline([...rows, invalid])
  assert.deepEqual(result.exported, rows)
  assert.equal(result.rejectedCount, 1)
  assert.deepEqual(result.rejectedReasons, ['invalid-sku'])
})

test('pipeline: empty input yields empty result', () => {
  const result = exportPipeline([])
  assert.deepEqual(result.exported, [])
  assert.equal(result.rejectedCount, 0)
  assert.deepEqual(result.rejectedReasons, [])
})
